mesSim(document.getElementById("sim-l79"),Object.assign({id:"l79"},{kind:"api",title:"Nút trên màn hình trạm là một giao dịch",sub:"POST /work-orders/{wo_id}/{action}: khóa dòng (FOR UPDATE), kiểm tra transition(), ghi lịch sử, COMMIT.",
 store:{wo:{"WO-0412":"RELEASED"},hist:[]},method:"POST",path:"/work-orders/WO-0412/start",
 routes:[{m:"POST",p:"/work-orders/{wo}/{action}",d:"start · pause · resume · complete",h:({params,store})=>{const A={start:"RUNNING",pause:"PAUSED",resume:"RUNNING",complete:"COMPLETED"};
    const L={NEW:["RELEASED","CANCELLED"],RELEASED:["RUNNING","CANCELLED"],RUNNING:["PAUSED","COMPLETED"],PAUSED:["RUNNING","COMPLETED","CANCELLED"],COMPLETED:[],CANCELLED:[]};
    if(!(params.action in A))return{status:422,body:{detail:[{loc:["path","action"],msg:"Input should be 'start', 'pause', 'resume' or 'complete'",type:"literal_error",input:params.action}]}};
    const cur=store.wo[params.wo];if(!cur)return{status:404,body:{detail:"Không có lệnh"}};const to=A[params.action];
    if(params.action==="resume"&&cur!=="PAUSED"||!L[cur].includes(to))return{status:409,body:{detail:cur+" → "+to+" không hợp lệ"}};
    store.wo[params.wo]=to;store.hist.push({wo_id:params.wo,from_st:cur,to_st:to,by_user:"to.truong.an"});return{status:200,body:{wo_id:params.wo,status:to}}}},
  {m:"GET",p:"/work-orders/{wo}/history",d:"wo_transition",h:({params,store})=>({status:200,body:store.hist.filter(h=>h.wo_id===params.wo)})}],
 samples:[{l:"start",m:"POST",p:"/work-orders/WO-0412/start"},{l:"pause",m:"POST",p:"/work-orders/WO-0412/pause"},{l:"resume",m:"POST",p:"/work-orders/WO-0412/resume"},{l:"complete",m:"POST",p:"/work-orders/WO-0412/complete"},{l:"Lịch sử",m:"GET",p:"/work-orders/WO-0412/history"}],
 tasks:[{t:"Bắt đầu WO-0412.",check:(s,c)=>c.has("http",e=>/start$/.test(e.path)&&e.status===200)},
  {t:"Bấm start lần nữa (hai tổ trưởng cùng bấm).",ok:"409 Conflict: RUNNING → RUNNING không hợp lệ; dữ liệu giữ nguyên.",check:(s,c)=>c.has("http",e=>e.status===409)},
  {t:"Gửi action không có, ví dụ /stop.",ok:"422: Literal chặn ngay ở đường dẫn.",check:(s,c)=>c.has("http",e=>e.status===422)},
  {t:"Tạm dừng, chạy tiếp, hoàn tất; rồi xem lịch sử.",ok:"4 dòng wo_transition: tính được lệnh tạm dừng bao lâu, ai bấm hoàn tất.",check:(s,c)=>c.has("http",e=>/history/.test(e.path)&&Array.isArray(e.body)&&e.body.length>=4)}]}));

